// @ts-check

/**
 * Bare module specifiers that the TacPhone host provides through the import map.
 *
 * This is the single source of truth for:
 * - the import map generated by the host vite.config.ts,
 * - the module map installed by the host src/main.tsx,
 * - the host's Vite `resolve.dedupe` list,
 * - the external list used by app builds, and
 * - check-shared-imports.
 *
 * The module namespace is published on the internal `window.TacPhone.modules`
 * map under `specifier`, not on a per-module window global.
 *
 * @typedef {'react' | 'react-dom' | 'react-dom/client' | 'react/jsx-runtime' | 'react/compiler-runtime' | 'qrcode-generator'} SharedModuleSpecifier
 * @typedef {{ readonly specifier: SharedModuleSpecifier }} SharedModule
 */

/** @type {readonly SharedModule[]} */
export const SHARED_MODULES = Object.freeze([
    Object.freeze({ specifier: 'react' }),
    Object.freeze({ specifier: 'react-dom' }),
    Object.freeze({ specifier: 'react-dom/client' }),
    Object.freeze({ specifier: 'react/jsx-runtime' }),
    Object.freeze({ specifier: 'react/compiler-runtime' }),
    Object.freeze({ specifier: 'qrcode-generator' }),
]);

/** @type {readonly SharedModuleSpecifier[]} */
export const SHARED_MODULE_SPECIFIERS = Object.freeze(
    SHARED_MODULES.map(({ specifier }) => specifier),
);
